/**
 * Accepts a multipart/form-data upload containing a PDF file and optional
 * metadata. Extracts text from the PDF and stores the file in object
 * storage. Returns the created source record with extracted text.
 * @summary Upload a PDF file as a source for a project
 */
export const uploadPdfSource = async (id: string,
    pdfSourceUpload: PdfSourceUpload, options?: Parameters<typeof customFetch>[1]): Promise<Source> => {
    const formData = new FormData();
formData.append(`file`, pdfSourceUpload.file);
if(pdfSourceUpload.title !== undefined) {
 formData.append(`title`, pdfSourceUpload.title);
 }
if(pdfSourceUpload.publisher !== undefined) {
 formData.append(`publisher`, pdfSourceUpload.publisher);
 }
if(pdfSourceUpload.author !== undefined) {
 formData.append(`author`, pdfSourceUpload.author);
 }
if(pdfSourceUpload.publicationDate !== undefined) {
 formData.append(`publicationDate`, pdfSourceUpload.publicationDate);
 }

  return customFetch<Source>(getUploadPdfSourceUrl(id),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





